"use strict";(globalThis.webpackChunklearngenomics_dev||=[]).push([[4394],{4546(e,n,a){a.r(n),a.d(n,{assets:()=>h,contentTitle:()=>l,default:()=>u,frontMatter:()=>c,metadata:()=>r,toc:()=>d});var s=a.cw((e,n)=>{const s=a.p+"assets/images/2.1-clonal-expansion-dark-8185ff37ce939d858ef9f5163b042c42.svg";a.d(n,["A",0,s])}),t=a.cw((e,n)=>{const s=a.p+"assets/images/2.1-clonal-expansion-ffc562a6cec98dcb31e6a33ab5c6a79f.svg";a.d(n,["A",0,s])});const r=JSON.parse('{"id":"cancer-biology/what-is-cancer","title":"What Is Cancer?","description":"There were close to 20 million new cases of cancer worldwide in 2022, and 9.7 million","source":"@site/docs/02-cancer-biology/01-what-is-cancer.md","sourceDirName":"02-cancer-biology","slug":"/cancer-biology/what-is-cancer","permalink":"/docs/cancer-biology/what-is-cancer","draft":false,"unlisted":false,"editUrl":"https://github.com/stjude/learngenomics.dev/tree/main/docs/02-cancer-biology/01-what-is-cancer.md","tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"title":"What Is Cancer?"},"sidebar":"tutorialSidebar","previous":{"title":"Introduction","permalink":"/docs/cancer-biology/introduction"},"next":{"title":"Hallmarks of Cancer","permalink":"/docs/cancer-biology/hallmarks-of-cancer"}}');var o=a(4848),i=a(8453);const c={title:"What Is Cancer?"},l=void 0,h={},d=[{value:"Cells That Stop Cooperating",id:"cells-that-stop-cooperating",level:2},{value:"Tumors",id:"tumors",level:2},{value:"How Cancer Starts",id:"how-cancer-starts",level:2},{value:"Types of Cancer",id:"types-of-cancer",level:2},{value:"Cancer in Children",id:"cancer-in-children",level:2},{value:"Up Next",id:"up-next",level:2}];function m(e){const n={a:"a",figcaption:"figcaption",figure:"figure",h2:"h2",img:"img",li:"li",p:"p",span:"span",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(n.p,{children:["There were close to 20 million new cases of cancer worldwide in 2022, and 9.7 million\ndeaths from it (",(0,o.jsx)(n.a,{href:"https://doi.org/10.3322/caac.21834",children:"Bray et al., 2024"}),"). An estimated\none in five people will develop cancer at some point in their lives. The word covers\nwell over a hundred different diseases, and in the low to mid hundreds once they are\nsplit by the genetic changes that drive them. They start in different tissues and behave\nin very different ways. This page explains what those diseases have in common, how a\ncancer begins and how the main types are named. The rest of the chapter looks more\nclosely at the genes involved and at how a tumor changes as it grows."]}),"\n",(0,o.jsx)(n.h2,{id:"cells-that-stop-cooperating",children:"Cells That Stop Cooperating"}),"\n",(0,o.jsx)(n.p,{children:"A human body is built from trillions of cells, and nearly all of them carry the same\ngenome. Living together takes restraint. A cell divides only when the body needs new\ncells, does the specialized job of its tissue and dies when it is damaged or no longer\nneeded. Neighboring cells, chemical signals and the cell's own genes enforce these\nrules."}),"\n",(0,o.jsxs)(n.p,{children:["Cancer is a disease in which some of the body's cells grow uncontrollably and spread to\nother parts of the body (",(0,o.jsx)(n.a,{href:"https://www.cancer.gov/about-cancer/understanding/what-is-cancer",children:"National Cancer\nInstitute"}),").\nBiologists who study cancer across many species describe it as a breakdown of\ncooperation (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1098/rstb.2014.0219",children:"Aktipis et al., 2015"}),"). Cancer\ncells divide when they should stop, avoid the death that would remove them, abandon the\nspecialized work of their tissue, take more than their share of resources and damage the\nenvironment around them. The ",(0,o.jsx)(n.a,{href:"/docs/cancer-biology/hallmarks-of-cancer",children:"next page"})," breaks these\nabilities down into the hallmarks of cancer."]}),"\n",(0,o.jsx)(n.h2,{id:"tumors",children:"Tumors"}),"\n",(0,o.jsxs)(n.p,{children:["Extra cells often build up into a lump of tissue called a ",(0,o.jsx)(n.strong,{children:"tumor"}),". Not every tumor is\ncancer."]}),"\n",(0,o.jsxs)(n.p,{children:["A ",(0,o.jsx)(n.strong,{children:"benign"})," tumor grows in place. It does not invade nearby tissue or spread, and once\nremoved it usually does not grow back. Benign tumors can still be dangerous when they\ngrow large or press on something vital, as some brain tumors do."]}),"\n",(0,o.jsxs)(n.p,{children:["A ",(0,o.jsx)(n.strong,{children:"malignant"})," tumor is cancer. Its cells ",(0,o.jsx)(n.strong,{children:"invade"})," the tissue around them, and some\ncan break away, travel through the blood or lymph system and start new tumors elsewhere\nin the body. This spread is called ",(0,o.jsx)(n.strong,{children:"metastasis"}),", and most deaths from cancer are\ncaused by cancer that has spread. A tumor that grows from cells that have spread keeps\nthe name of the original, or ",(0,o.jsx)(n.strong,{children:"primary"}),", tumor. Breast cancer that spreads to the lung\nis metastatic breast cancer, and its cells still look like breast cells under a\nmicroscope."]}),"\n",(0,o.jsxs)(n.p,{children:["Some changes come before cancer. In ",(0,o.jsx)(n.strong,{children:"hyperplasia"}),", cells divide faster than normal and\nbuild up, but they look normal. In ",(0,o.jsx)(n.strong,{children:"dysplasia"}),", the extra cells also look abnormal.\n",(0,o.jsx)(n.strong,{children:"Carcinoma in situ"})," is a group of abnormal cells that has not invaded nearby tissue.\nIt is sometimes called stage 0 cancer, but none of these changes is cancer. Some can\nbecome cancer, so they are often watched or treated (",(0,o.jsx)(n.a,{href:"https://www.cancer.gov/about-cancer/understanding/what-is-cancer#tissue-changes-that-are-not-cancer",children:"National Cancer\nInstitute"}),")."]}),"\n",(0,o.jsxs)(n.p,{children:["Not every cancer forms a lump. ",(0,o.jsx)(n.strong,{children:"Leukemias"}),", cancers of the blood-forming tissue in the\nbone marrow, fill the blood and bone marrow with abnormal white blood cells instead."]}),"\n",(0,o.jsx)(n.h2,{id:"how-cancer-starts",children:"How Cancer Starts"}),"\n",(0,o.jsxs)(n.p,{children:["Cancer is a genetic disease. It is caused by changes to the genes that control how cells\nbehave, especially how they grow and divide. Some of these changes are inherited from a\nparent. Most arise during a person's lifetime, either from errors made when a cell\ncopies its DNA before dividing or from DNA damage caused by exposures such as the\nchemicals in tobacco smoke and ultraviolet light from the sun. The body normally removes\ncells with damaged DNA, but it gets worse at this with age. Age is the single most\nimportant risk factor for cancer, and the median age at diagnosis in the United States\nis 67 (",(0,o.jsx)(n.a,{href:"https://www.cancer.gov/about-cancer/causes-prevention/risk/age",children:"National Cancer\nInstitute"}),")."]}),"\n",(0,o.jsxs)(n.p,{children:["A single change is rarely enough. Peter Nowell proposed in 1976 that most tumors arise\nfrom one cell, and that a tumor progresses as its cells acquire new changes and the most\naggressive ones are selected (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1126/science.959840",children:"Nowell, 1976"}),"). A\ncell gains a change that lets it divide a little more often than its neighbors, so its\ndescendants slowly outnumber them. One of those descendants gains a second change and\noutgrows the rest, and the process repeats. In some tumors, cells eventually gain the\nability to invade. Each new change of this kind sets off another wave of growth, and the\ntumor gets larger and more disordered with each one (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1016/0168-9525(93)90209-z",children:"Vogelstein and Kinzler,\n1993"}),"; ",(0,o.jsx)(n.a,{href:"https://doi.org/10.1038/nature10762",children:"Greaves and Maley,\n2012"}),")."]}),"\n",(0,o.jsxs)(n.figure,{className:"lg-figure lg-figure--tall lg-figure--themed",id:"figure-2-1",children:[(0,o.jsx)(n.img,{alt:"Four rows of cells on a basement membrane show a tumor developing over time. In row 1, a single cell in an ordinary layer of cells gains a first mutation. In row 2, that cell's descendants have spread along the layer and begun to pile up. In row 3, one of those descendants has gained a second mutation, and its own descendants form a larger mound within the first group. In row 4, a cell in the mound gains a third mutation, and its descendants break through the basement membrane into the tissue below.",src:t().A+"",width:"392",height:"606"}),(0,o.jsx)(n.img,{className:"lg-figure__dark",src:s().A,alt:"Four rows of cells on a basement membrane show a tumor developing over time. In row 1, a single cell in an ordinary layer of cells gains a first mutation. In row 2, that cell's descendants have spread along the layer and begun to pile up. In row 3, one of those descendants has gained a second mutation, and its own descendants form a larger mound within the first group. In row 4, a cell in the mound gains a third mutation, and its descendants break through the basement membrane into the tissue below.",width:"392",height:"605.6",loading:"lazy",decoding:"async"}),(0,o.jsxs)(n.figcaption,{children:[(0,o.jsx)(n.span,{className:"lg-figure__number",children:"Figure 2.1"})," A tumor grows from a single cell. Each new mutation that helps a cell divide or survive lets that cell's descendants outgrow their neighbors. After several such steps, some cells break through the basement membrane, the thin layer beneath them, and invade the tissue below. Each row is a later point in time. The figure shows one route to a carcinoma, a cancer of the cells that line a surface, and the number of mutations is only an example. Based on the multistep model of Vogelstein and Kinzler (1993)."]})]}),"\n",(0,o.jsxs)(n.p,{children:["The changes that push a cell along this path are called ",(0,o.jsx)(n.strong,{children:"driver mutations"}),". Across\nmore than 7,600 tumors of 29 types, the average tumor carried about four driver\nmutations that change a single base in a protein-coding gene. Thyroid and testicular\ncancers averaged fewer than one, and colorectal and endometrial cancers more than ten\n(",(0,o.jsx)(n.a,{href:"https://doi.org/10.1016/j.cell.2017.09.042",children:"Martincorena et al., 2017"}),"). Those counts\nleave out larger changes, such as gained or lost chromosome segments, which can drive\ncancer too. Most of the other mutations in a tumor are ",(0,o.jsx)(n.strong,{children:"passengers"})," that came along\nfor the ride. ",(0,o.jsx)(n.a,{href:"/docs/cancer-biology/oncogenes-and-tumor-suppressors",children:"Oncogenes and Tumor Suppressors"}),"\nexplains which genes the drivers hit, and ",(0,o.jsx)(n.a,{href:"/docs/cancer-biology/how-tumors-evolve",children:"How Tumors Evolve"}),"\nfollows the descendants of that first cell further."]}),"\n",(0,o.jsx)(n.p,{children:"Because every tumor follows its own path, each one carries its own combination of\nchanges, and cells within the same tumor can differ from one another. Two patients with\nthe same type of cancer can have tumors that are genetically very different."}),"\n",(0,o.jsx)(n.h2,{id:"types-of-cancer",children:"Types of Cancer"}),"\n",(0,o.jsxs)(n.p,{children:["Cancers are usually named for the organ or tissue where they start, so lung cancer\nstarts in the lung even if it later spreads to the brain. Worldwide, the most commonly\ndiagnosed cancers are lung, female breast, colorectal, prostate and stomach cancers\n(",(0,o.jsx)(n.a,{href:"https://doi.org/10.3322/caac.21834",children:"Bray et al., 2024"}),")."]}),"\n",(0,o.jsx)(n.p,{children:"Cancers are also grouped by the kind of cell they start in. The main groups are:"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Carcinomas"})," start in epithelial cells, which line the inside and outside surfaces\nof the body. They are the most common type of cancer, and most breast, colon, lung and\nprostate cancers are carcinomas."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Sarcomas"})," start in bone and in soft tissues such as muscle, fat and blood vessels.\nOsteosarcoma is the most common cancer of bone."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Leukemias"})," start in the blood-forming tissue of the bone marrow. The four common types\nare acute lymphoblastic, acute myeloid, chronic lymphocytic and chronic myeloid\nleukemia."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Lymphomas"})," start in lymphocytes, the T cells and B cells of the immune system. The\ntwo main types are Hodgkin and non-Hodgkin lymphoma."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Multiple myeloma"})," starts in plasma cells, the immune cells that make antibodies."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Melanoma"})," starts in melanocytes, the cells that make the pigment that colors skin.\nMost melanomas form on the skin."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Brain and spinal cord tumors"})," are named for the cell they start in and where in the\nnervous system they form."]}),"\n"]}),"\n",(0,o.jsxs)(n.p,{children:["These groups are only the first level. Within each, cancers are split by the exact cell\ntype and, more and more, by the driver changes they carry. The World Health Organization\nnow names some brain tumors by their driver, such as IDH-mutant astrocytoma (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1093/neuonc/noab106",children:"Louis et\nal., 2021"}),"). Experts don't always agree on where\nthe lines fall. In 2022, two expert groups published separate classifications of myeloid\nleukemias that differ in several places (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1038/s41375-022-01613-1",children:"Khoury et al.,\n2022"}),"; ",(0,o.jsx)(n.a,{href:"https://doi.org/10.1182/blood.2022015850",children:"Arber et al.,\n2022"}),"). That is why one source counts more\nthan 100 types of cancer (",(0,o.jsx)(n.a,{href:"https://www.cancer.gov/about-cancer/understanding/what-is-cancer",children:"National Cancer\nInstitute"}),") and\nanother more than 200 (",(0,o.jsx)(n.a,{href:"https://www.cancerresearchuk.org/about-cancer/what-is-cancer",children:"Cancer Research\nUK"}),")."]}),"\n",(0,o.jsx)(n.h2,{id:"cancer-in-children",children:"Cancer in Children"}),"\n",(0,o.jsxs)(n.p,{children:["Cancer in children is rare. Only about 1% of cancers in the United States are diagnosed\nin people under 20 (",(0,o.jsx)(n.a,{href:"https://www.cancer.gov/about-cancer/causes-prevention/risk/age",children:"National Cancer\nInstitute"}),"). The most\ncommon types are different from those in adults. Leukemias come first, followed by brain\nand other central nervous system tumors and then lymphomas (",(0,o.jsx)(n.a,{href:"https://www.cancer.gov/types/childhood-cancers/child-adolescent-cancers-fact-sheet",children:"National Cancer\nInstitute"}),").\nCarcinomas, so common in adults, are much less common."]}),"\n",(0,o.jsxs)(n.p,{children:["The genomes of childhood cancers look different too. A study of 1,699 childhood\nleukemias and solid tumors found lower rates of single-base mutations than in common\nadult cancers. Of the 142 driver genes it identified, only 45% matched those found in\nadult cancers, and most driver events were copy number changes and structural variants\nrather than changes to single bases (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1038/nature25795",children:"Ma et al.,\n2018"}),"). Some children also carry a germline\nvariant, present in every cell of the body, that raises their risk. Such variants can be\ninherited from a parent or arise new in the child. In a second study of 961 tumors from\nchildren, adolescents and young adults, 7\u20138% of the patients carried one that clearly\npredisposed them to cancer (",(0,o.jsx)(n.a,{href:"https://doi.org/10.1038/nature25480",children:"Gr\xf6bner et al.,\n2018"}),"). ",(0,o.jsx)(n.a,{href:"/docs/cancer-biology/inherited-risk",children:"Inherited Risk"}),"\nreturns to these."]}),"\n",(0,o.jsx)(n.h2,{id:"up-next",children:"Up Next"}),"\n",(0,o.jsxs)(n.p,{children:["Cancer cells break the rules that let trillions of cells live together. ",(0,o.jsx)(n.a,{href:"/docs/cancer-biology/hallmarks-of-cancer",children:"Hallmarks of\nCancer"})," lists the abilities a cell needs to break them."]})]})}function u(e={}){const{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(m,{...e})}):m(e)}},8453(e,n,a){a.d(n,{R:()=>o,x:()=>i});var s=a(6540);const t={},r=s.createContext(t);function o(e){const n=s.useContext(r);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function i(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:o(e.components),s.createElement(r.Provider,{value:n},e.children)}}}]);